import{d as c,C as t,o as m,c as u,j as a,a as s,E as r,a3 as p}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第三十二章","description":"从道常无名与守朴，理解名分建立后的知止，以及不令而自均的治理取向。","frontmatter":{"title":"道德经第三十二章","description":"从道常无名与守朴，理解名分建立后的知止，以及不令而自均的治理取向。","category":"guide","aliases":["道德经第三十二章","老子第三十二章","dao de jing chapter 32"],"source":["王弼《道德真经注》卷二"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-32.md","filePath":"daoism/dao-de-jing/chapter-32.md","lastUpdated":1794189804000}'),b={name:"daoism/dao-de-jing/chapter-32.md"},y=c({...b,setup(g){const i=[{id:"nameless-dao-and-uncarved-simplicity",label:"朴虽小，天下莫能臣也",showLabel:!0,sentences:[["道常",{text:"无名",glossary:"wuming"},"。"],[{text:"朴",glossary:"pu"},"虽小，天下莫能",{text:"臣",glossary:"chen"},"也。"]],note:["【白话】道恒常无可固定称定的名称。质朴未分的本真虽似微小，天下却没有谁能使它臣服、把它当作一种专门的工具来役使。","【王弼注择要】「道无形不系，常不可名。」注又说「樸之为物，以无为心也」，并以智、勇、巧、力可以受役使，说明朴不偏于某一种能力。引文中的樸即本站正文的朴。","【读法】无名不只是尚未来得及命名；本章循王弼，重在不可由固定名目限定。朴虽小沿本站保留，不能假称已在所据录文正文逐字见到。"]},{id:"rulers-preserving-simplicity",label:"侯王若能守之，万物将自宾",showLabel:!0,sentences:[[{text:"侯王",glossary:"houwang"},"若能守之，万物将自",{text:"宾",glossary:"bin"},"。"]],note:["【白话】侯王若能守住这种无名之朴，万物便将自行归从。这里提出的是在上者不以私欲和外物扰其本真的治理取向。","【王弼注择要】「不以物累其真，不以欲害其神，则物自宾而道自得也。」王弼以不受物欲牵累说明守朴，不将自宾解释成强力征服。","【读法】之承接无名之道与朴。万物自宾是本章理想的秩序图景，不能当作只要少做事就能自动获得服从的现实保证。"]},{id:"harmony-without-coercive-orders",label:"民莫之令而自均",showLabel:!0,sentences:[["天地相合，以降",{text:"甘露",glossary:"ganlu"},"，民莫之令而自",{text:"均",glossary:"jun"},"。"]],note:["【白话】天地相互和合，甘露因而降下；百姓无需受到逐一强令，便自行趋于均平。前后两句以自然和合比照不妄加号令的治理。","【王弼注择要】「甘露不求而自降」，又说「我守其真性无为，则民不令而自均也」。注把不求、不令连到守真无为，着重秩序不全靠强制产生。","【读法】民莫之令是没有谁命令他们的倒装说法。天地甘露是本章的譬说，不作为现代气象解释；自均也不等于放任不管、取消必要的公共责任。"]},{id:"names-with-limits",label:"名亦既有，夫亦将知止",showLabel:!0,sentences:[[{text:"始制",glossary:"shizhi"},"有",{text:"名",glossary:"ming"},"，名亦既有，夫亦将",{text:"知止",glossary:"zhizhi"},"，知止可以不",{text:"殆",glossary:"dai"},"。"]],note:["【白话】开始建立制度、设置职任，就有了相应的名称与名分；名分既已建立，也应知道在哪里停止。知道限度，才可以避免陷入危殆。","【王弼注择要】「始制，谓樸散始为官长之时也。」注承认立名分的需要，又警戒「将争锥刀之末」，并说「遂任名以号物，则失治之母也」。","【读法】本页依王弼，从官长、名分的古代治理背景解释始制有名。知止不是一概废弃名称，而是不让立名越过必要的分际，变成无休止的争逐。"]},{id:"streams-and-the-sea",label:"犹川谷之于江海",showLabel:!0,sentences:[["譬道之在天下，犹川谷之于江海。"]],note:["【白话】以道行于天下来作比，好像川谷之水趋向江海：不必逐一召令，它们便自行归往。末句以水的归流收束自宾、自均的意思。","【王弼注择要】「不召不求而自归」，又说行道于天下「不令而自均，不求而自得」。本页据此理解川谷与江海的譬喻，重在归流不靠强召。","【读法】譬喻说明不强求而成其归往，不必把道、天下、川谷、江海的每一项都机械地对应成固定图式。"]}],n=[{id:"wuming",term:"无名",sense:2},{id:"pu",term:"朴",sense:2},{id:"chen",term:"臣",sense:1},{id:"houwang",term:"侯王",sense:1},{id:"bin",term:"宾",sense:1},{id:"ganlu",term:"甘露",sense:1},{id:"jun",term:"均",sense:1},{id:"shizhi",term:"始制",sense:1},{id:"ming",term:"名",sense:2},{id:"zhizhi",term:"知止",sense:1},{id:"dai",term:"殆",sense:1}];return(x,e)=>{const o=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return m(),u("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第三十二章",tabindex:"-1"},[s("道德经第三十二章 "),a("a",{class:"header-anchor",href:"#道德经第三十二章","aria-label":'Permalink to "道德经第三十二章"'},"​")],-1)),r(o,{title:"既要立名分，为什么又要知止",summary:"本章从无名之道与未分之朴起笔，写侯王守之、万物自宾，再以甘露和川谷归海说明不强令而自成的秩序；名分虽不可全无，却不能无限扩张。",points:[{label:"先读",text:"无名与朴相连，先看道为何不能被某一专长或名目占尽。"},{label:"再辨",text:"守朴、自宾、自均相贯，重点是不以欲望与号令强制万物。"},{label:"后看",text:"始制有名承认名分的作用，知止则限制逐名与过度分别。"}],hint:"臣在此作使之臣服；宾作归从。朴虽小沿本站保留，所据录文正文未见此三字，注中则有守朴之说。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),r(l,{sections:i,glossary:n}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),r(d,{lines:[{text:"朴虽小，天下莫能臣也。",tone:"未分之朴不受役使",guide:"王弼以不偏于智勇巧力说明朴，不把它缩为一种可供征服使用的本领。"},{text:"始制有名，名亦既有，夫亦将知止，知止可以不殆。",tone:"立名也要有分际",guide:"承认职任与名分的用途，同时警戒对细末利益和名号的无尽争逐。"},{text:"譬道之在天下，犹川谷之于江海。",tone:"不强召而自归",guide:"把末句与自宾、自均相连，读出守朴而少强制的贯通线索。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),r(h,{items:n}),e[4]||(e[4]=p("",15))])}}});export{_ as __pageData,y as default};
